import pandas as pd

def clean(df):
    df = df.copy()

    if "Price" in df.columns:
        df["Price"] = (
            df["Price"].astype(str)
            .str.replace(r"[$,]", "", regex=True)
            .str.strip()
        )
        df["Price"] = pd.to_numeric(df["Price"], errors="coerce")

    if "Quantity" in df.columns:
        df["Quantity"] = pd.to_numeric(df["Quantity"], errors="coerce")
        df["Quantity"] = df["Quantity"].abs().round().astype("Int64")

    if "Region" in df.columns:
        df["Region"] = df["Region"].astype(str).str.strip().str.title()

    if "Category" in df.columns:
        df["Category"] = df["Category"].astype(str).str.strip()

    if all(c in df.columns for c in ["Quantity", "Price", "Revenue"]):
        df["Revenue"] = df["Quantity"].astype(float) * df["Price"]

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=["Category", "Price"])
    result = d.groupby("Category", dropna=True)["Price"].mean()
    return {str(k): float(v) for k, v in result.items()}
